  }

  .index-intro {
    padding: var(--spacing-lg) 0;
  }

  .index-movies {
    padding: var(--spacing-lg) 0;
  }

  .index-movie-card .card-image {
    height: 250px;
  }

  .index-booking {
    padding: var(--spacing-lg) 0;
